import java.io.*;

public class Main {
    static final int K = 1010;
    static final long MOD = 1_000_000_007L;
    static final long[][] dp = new long[K][K];

    static long powMod(long a, long exponent) {
        if (exponent == 0) return 1;
        if (exponent % 2 == 0) {
            return powMod(a * a % MOD, exponent / 2);
        }
        return a * powMod(a, exponent - 1) % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int k = fs.nextInt();
        long va = fs.nextLong();
        long vb = fs.nextLong();

        long den = powMod((va + vb) % MOD, MOD - 2);
        long pa = va * den % MOD;
        long pb = vb * den % MOD;
        long oneB = pa * powMod(pb, MOD - 2) % MOD;

        for (int i = k - 1; i >= 0; i--) {
            for (int j = k; j >= 1; j--) {
                if (i + j >= k) {
                    dp[i][j] = (i + j + oneB) % MOD;
                } else {
                    dp[i][j] = (pa * dp[i][j + 1]
                            + pb * dp[i + j][j]) % MOD;
                }
            }
        }

        System.out.println(dp[0][1]);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

